macro_rules! deps {
    () => {
        Limb!();
        VecType!();
    };
}

macro_rules! long_mul {
    () => {
        deps!();
        # [doc = " Grade-school multiplication algorithm."] # [doc = ""] # [doc = " Slow, naive algorithm, using limb-bit bases and just shifting left for"] # [doc = " each iteration. This could be optimized with numerous other algorithms,"] # [doc = " but it's extremely simple, and works in O(n*m) time, which is fine"] # [doc = " by me. Each iteration, of which there are `m` iterations, requires"] # [doc = " `n` multiplications, and `n` additions, or grade-school multiplication."] # [doc = ""] # [doc = " Don't use Karatsuba multiplication, since out implementation seems to"] # [doc = " be slower asymptotically, which is likely just due to the small sizes"] # [doc = " we deal with here. For example, running on the following data:"] # [doc = ""] # [doc = " ```text"] # [doc = " const SMALL_X: &[u32] = &["] # [doc = "     766857581, 3588187092, 1583923090, 2204542082, 1564708913, 2695310100, 3676050286,"] # [doc = "     1022770393, 468044626, 446028186"] # [doc = " ];"] # [doc = " const SMALL_Y: &[u32] = &["] # [doc = "     3945492125, 3250752032, 1282554898, 1708742809, 1131807209, 3171663979, 1353276095,"] # [doc = "     1678845844, 2373924447, 3640713171"] # [doc = " ];"] # [doc = " const LARGE_X: &[u32] = &["] # [doc = "     3647536243, 2836434412, 2154401029, 1297917894, 137240595, 790694805, 2260404854,"] # [doc = "     3872698172, 690585094, 99641546, 3510774932, 1672049983, 2313458559, 2017623719,"] # [doc = "     638180197, 1140936565, 1787190494, 1797420655, 14113450, 2350476485, 3052941684,"] # [doc = "     1993594787, 2901001571, 4156930025, 1248016552, 848099908, 2660577483, 4030871206,"] # [doc = "     692169593, 2835966319, 1781364505, 4266390061, 1813581655, 4210899844, 2137005290,"] # [doc = "     2346701569, 3715571980, 3386325356, 1251725092, 2267270902, 474686922, 2712200426,"] # [doc = "     197581715, 3087636290, 1379224439, 1258285015, 3230794403, 2759309199, 1494932094,"] # [doc = "     326310242"] # [doc = " ];"] # [doc = " const LARGE_Y: &[u32] = &["] # [doc = "     1574249566, 868970575, 76716509, 3198027972, 1541766986, 1095120699, 3891610505,"] # [doc = "     2322545818, 1677345138, 865101357, 2650232883, 2831881215, 3985005565, 2294283760,"] # [doc = "     3468161605, 393539559, 3665153349, 1494067812, 106699483, 2596454134, 797235106,"] # [doc = "     705031740, 1209732933, 2732145769, 4122429072, 141002534, 790195010, 4014829800,"] # [doc = "     1303930792, 3649568494, 308065964, 1233648836, 2807326116, 79326486, 1262500691,"] # [doc = "     621809229, 2258109428, 3819258501, 171115668, 1139491184, 2979680603, 1333372297,"] # [doc = "     1657496603, 2790845317, 4090236532, 4220374789, 601876604, 1828177209, 2372228171,"] # [doc = "     2247372529"] # [doc = " ];"] # [doc = " ```"] # [doc = ""] # [doc = " We get the following results:"] # [doc = " ```text"] # [doc = " mul/small:long          time:   [220.23 ns 221.47 ns 222.81 ns]"] # [doc = " Found 4 outliers among 100 measurements (4.00%)"] # [doc = "   2 (2.00%) high mild"] # [doc = "   2 (2.00%) high severe"] # [doc = " mul/small:karatsuba     time:   [233.88 ns 234.63 ns 235.44 ns]"] # [doc = " Found 11 outliers among 100 measurements (11.00%)"] # [doc = "   8 (8.00%) high mild"] # [doc = "   3 (3.00%) high severe"] # [doc = " mul/large:long          time:   [1.9365 us 1.9455 us 1.9558 us]"] # [doc = " Found 12 outliers among 100 measurements (12.00%)"] # [doc = "   7 (7.00%) high mild"] # [doc = "   5 (5.00%) high severe"] # [doc = " mul/large:karatsuba     time:   [4.4250 us 4.4515 us 4.4812 us]"] # [doc = " ```"] # [doc = ""] # [doc = " In short, Karatsuba multiplication is never worthwhile for out use-case."] pub fn long_mul (x : & [Limb] , y : & [Limb]) -> Option < VecType > { let mut z = VecType :: try_from (x) ? ; if ! y . is_empty () { let y0 = y [0] ; small_mul (& mut z , y0) ? ; for (index , & yi) in y . iter () . enumerate () . skip (1) { if yi != 0 { let mut zi = VecType :: try_from (x) ? ; small_mul (& mut zi , yi) ? ; large_add_from (& mut z , & zi , index) ? ; } } } z . normalize () ; Some (z) }
    };
}

long_mul!();